export const seedCustomerMonthly = Object.entries(CUSTOMER_MONTHLY_BRANCH_FACTORS).flatMap(
  ([branch, branchFactor]) =>
    Object.entries(CUSTOMER_MONTHLY_MONTH_FACTORS).flatMap(([month, monthFactor]) =>
      CUSTOMER_REKAP_BASE.map((base, index) => {
        const factor = branchFactor * monthFactor;
        const scale = (value) => Math.round(value * factor);
        return {
          id: `${branch}-${month}-${index + 1}`,
          branch,
          period: `2026-0${month}`,
          customer: base.customer,
          totalAwb: scale(base.totalAwb),
          kg: scale(base.kg),
          volume: scale(base.volume),
          totalTransaksi: scale(base.totalTransaksi),
        };
      }),
    ),
);

