const OM_BRANCH_FACTORS = { Jakarta: 1, Surabaya: 0.8, Bandung: 0.6 };

export const seedOmsetHarian = Object.entries(OM_BRANCH_FACTORS).flatMap(([branch, factor]) =>
  [5, 6, 7].flatMap((month) => {
    const daysInMonth = new Date(Date.UTC(2026, month, 0)).getUTCDate();
    return Array.from({ length: daysInMonth }, (_, i) => {
      const d = new Date(Date.UTC(2026, month - 1, 1 + i));
      const tanggal = d.toISOString().slice(0, 10);
      const scale = (value) => (value === null ? null : Math.round(value * factor));
      const weekend = d.getUTCDay() === 0 || d.getUTCDay() === 6;
      if (weekend) {
        return { branch, tanggal, tunai: null, bb: null, bl: 0, transfer: null, totalOmset: 0, darat: 0, laut: null, udara: null };
      }
      const bl = (i + 1) % 2 === 0 ? scale(20000) : 0;
      const tunai = i % 6 === 3 ? scale(15000) : null;
      const bb = i % 8 === 5 ? scale(10000) : null;
      const transfer = i % 10 === 7 ? scale(30000) : null;
      const totalOmset = (tunai ?? 0) + (bb ?? 0) + (bl ?? 0) + (transfer ?? 0);
      let darat = 0;
      let laut = null;
      let udara = 0;
      if (totalOmset > 0) {
        if (i % 7 === 3) {
          udara = Math.round(totalOmset / 4);
          darat = totalOmset - udara;
        } else if (i % 7 === 4) {
          laut = Math.round(totalOmset / 5);
          darat = totalOmset - laut;
        } else {
          darat = totalOmset;
        }
      } else {
        udara = i % 4 === 0 ? 0 : null;
      }
      return { branch, tanggal, tunai, bb, bl, transfer, totalOmset, darat, laut, udara };
    });
  }),
);

